import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s1-u14")

L(1, "Geen: negar substantivos", "Ik heb geen auto: «geen» substitui «een».",
  ["Negar substantivos com geen"],
  vocab=[V("v-geen","geen","nenhum|não","determiner",note="Nega substantivos sem artigo definido: ik heb geen tijd."),
         V("v-honger","honger","fome","noun","de",note="Ik heb honger = tenho fome."), V("v-dorst","dorst","sede","noun","de"),
         V("v-probleem","probleem","problema","noun","het","problemen")],
  ex=[("Ik heb geen auto.","Não tenho carro."),("Hij drinkt geen koffie.","Ele não bebe café."),("Geen probleem!","Não há problema!"),("Ik heb geen honger.","Não tenho fome.")],
  gram=[G("g-geen","Geen","**geen** nega um substantivo que teria **een** ou nenhum artigo: *ik heb een auto* → *ik heb **geen** auto*; *ik drink koffie* → *ik drink **geen** koffie*. Não se diz «niet een» nem «niet koffie».",
    [("Er is geen melk.","Não há leite."),("Ik heb geen kinderen.","Não tenho filhos.")],
    "Em português usamos sempre «não» antes do verbo; em neerlandês, para substantivos indefinidos, a negação está no próprio substantivo: «geen».")],
  review=["v-hebben","v-auto","v-tijd","v-koffie","v-kind"],
  exs=[
    MA([("geen","nenhum"),("honger","fome"),("dorst","sede"),("probleem","problema")], "Palavras desta lição.", ["v-geen","v-honger","v-dorst","v-probleem"]),
    MC("Como se diz «Não tenho carro»?", ["*Ik heb geen auto.","Ik heb niet een auto.|Com «een» a negação é «geen».","Ik niet heb auto.|Ordem errada."], "een → geen.", ["v-geen","v-auto"]),
    TR("pt-nl","Não tenho tempo.", ["Ik heb geen tijd"], "tijd sem artigo → geen tijd.", ["v-geen","v-tijd"], bank=["Ik","heb","geen","tijd","niet","een"]),
    TR("nl-pt","Geen probleem!", ["Não há problema","Sem problema","Não faz mal"], "Expressão muito comum.", ["v-probleem"]),
    TR("pt-nl","Tenho fome.", ["Ik heb honger"], "Com «hebben», como em português.", ["v-honger"]),
    FB("Ik drink ___ koffie, ik drink thee.", ["geen"], "koffie sem artigo → geen.", ["v-geen"], choices=["geen","niet","een"], tr="Não bebo café, bebo chá."),
    FE(["Ik","heb","niet","dorst."], 2, "geen", "dorst é um substantivo sem artigo → geen dorst.", ["v-dorst","v-geen"]),
    AR("probleem","o problema","het", "«Het probleem».", ["v-probleem"]),
    LI("Ik heb geen honger.", ["Ik heb geen honger"], "Não tenho fome.", "geen ≈ «rrêin» com g gutural.", ["v-honger","v-geen"]),
    DL([("Empregado","Wilt u nog iets drinken?","Quer beber mais alguma coisa?"),("Cliente","")], ["*Nee, dank u, ik heb geen dorst.","Nee, ik heb niet dorst.|Substantivo: geen dorst.","Ja, geen probleem.|Não responde à pergunta."], "geen dorst = não ter sede.", ["v-dorst"]),
  ], diff=2, mins=5)

L(2, "Niet: negar verbos e adjetivos", "Ik werk niet; het is niet koud.",
  ["Negar verbos, adjetivos e o resto da frase com niet"],
  vocab=[V("v-weten","weten","saber","verb",note="ik weet, jij weet. Ik weet het niet = não sei."), V("v-houden-van","houden van","gostar de|amar","expression",note="Ik houd van koffie = gosto de café (forte)."),
         V("v-kapot","kapot","avariado|partido","adjective"), V("v-open","open","aberto","adjective"), V("v-dicht","dicht","fechado","adjective")],
  ex=[("Ik werk vandaag niet.","Hoje não trabalho."),("Het is niet koud.","Não está frio."),("Ik weet het niet.","Não sei."),("De winkel is niet open.","A loja não está aberta.")],
  gram=[G("g-niet","Niet","**niet** nega verbos, adjetivos, advérbios e substantivos com artigo definido ou possessivo. Posição: **depois do objeto direto** e no fim da frase simples (*ik weet het niet*), mas **antes** de adjetivos (*niet koud*), preposições de lugar (*niet in Amsterdam*) e partes separáveis.",
    [("Ik ken hem niet.","Não o conheço."),("Hij woont niet in Utrecht.","Ele não vive em Utrecht."),("Dat is niet mijn fiets.","Essa não é a minha bicicleta.")],
    "O «não» português vem antes do verbo; o «niet» vai para trás, muitas vezes para o fim.")],
  review=["v-niet","v-koud","v-werken","v-vandaag"],
  exs=[
    MA([("weten","saber"),("kapot","avariado"),("open","aberto"),("dicht","fechado")], "Palavras desta lição.", ["v-weten","v-kapot","v-open","v-dicht"]),
    WO("Não sei.", ["Ik","weet","het","niet"], "niet no fim.", ["v-weten","v-niet"]),
    WO("Hoje não trabalho.", ["Ik","werk","vandaag","niet"], "niet depois do advérbio de tempo.", ["v-werken","v-niet"], alt=["Vandaag werk ik niet"]),
    MC("Qual está correta?", ["*Het is niet koud.","Het is geen koud.|«koud» é adjetivo: niet.","Het niet is koud.|O verbo fica em 2.º."], "Adjetivo → niet antes dele.", ["v-niet","v-koud"]),
    TR("pt-nl","A loja não está aberta.", ["De winkel is niet open"], "niet antes do adjetivo.", ["v-open"]),
    TR("nl-pt","Mijn fiets is kapot.", ["A minha bicicleta está avariada"], "kapot = avariado.", ["v-kapot"]),
    FE(["Ik","niet","weet","het."], 1, "weet het niet", "Ordem: ik weet het niet.", ["v-weten"]),
    FB("Hij woont ___ in Utrecht, hij woont in Leiden.", ["niet"], "Antes da preposição de lugar: niet in Utrecht.", ["v-niet"], choices=["niet","geen","nooit niet"], tr="Ele não vive em Utrecht, vive em Leiden."),
    CJ("weten","jij","___ jij het?", ["Weet"], "weten: jij weet (a raiz já acaba em t).", ["v-weten"]),
    LI("De supermarkt is dicht.", ["De supermarkt is dicht"], "O supermercado está fechado.", "dicht = fechado.", ["v-dicht"]),
  ], diff=2, mins=6)

L(3, "Niet ou geen?", "Escolher a negação certa.",
  ["Distinguir niet e geen em frases do dia a dia"],
  vocab=[V("v-roken","roken","fumar","verb"), V("v-hem","hem","o|ele (complemento)","pronoun",note="Ik ken hem niet = não o conheço."),
         V("v-kennen","kennen","conhecer","verb",note="Conhecer pessoas e lugares; «weten» é saber factos.")],
  ex=[("Ik rook niet.","Não fumo."),("Ik heb geen sigaretten.","Não tenho cigarros."),("Ik ken hem niet.","Não o conheço."),("Dat is geen goed idee.","Isso não é boa ideia.")],
  gram=[G("g-niet-geen","Niet ou geen?","Pergunte: há um substantivo com **een** ou **sem artigo**? → **geen**. Em todos os outros casos → **niet** (verbos, adjetivos, nomes próprios, substantivos com **de/het** ou possessivo).",
    [("Ik heb geen fiets.","(een fiets) → geen"),("Ik heb de fiets niet.","(de fiets) → niet"),("Dat is niet mijn fiets.","(mijn fiets) → niet")],
    "É o ponto de gramática que mais erros causa a falantes de português: vale a pena treinar.")],
  review=["v-niet","v-geen","v-weten"],
  exs=[
    MC("Ik heb ___ broer.", ["*geen","niet|«broer» seria «een broer»: geen."], "een broer → geen broer.", ["v-geen","v-broer"]),
    MC("Ik ken ___ .", ["*hem niet","geen hem|Pronomes negam-se com niet.","niet hem|niet vem depois do pronome objeto."], "pronome → niet depois dele.", ["v-kennen","v-hem"]),
    MC("Dat is ___ mijn tas.", ["*niet","geen|Com possessivo usa-se niet."], "Possessivo → niet.", ["v-niet"]),
    MC("Hij rookt ___ .", ["*niet","geen|Verbo → niet."], "Negar o verbo → niet.", ["v-roken"]),
    MA([("roken","fumar"),("kennen","conhecer"),("weten","saber"),("hem","o (ele)")], "kennen vs weten.", ["v-roken","v-kennen","v-weten","v-hem"]),
    TR("pt-nl","Não fumo.", ["Ik rook niet"], "Verbo → niet.", ["v-roken"]),
    TR("pt-nl","Não tenho bicicleta.", ["Ik heb geen fiets"], "een fiets → geen fiets.", ["v-geen","v-fiets"]),
    TR("nl-pt","Dat is geen goed idee.", ["Isso não é (uma )boa ideia"], "een goed idee → geen goed idee.", ["v-geen"]),
    FE(["Ik","ken","niet","Amsterdam."], 2, "Amsterdam niet", "Nome próprio: ik ken Amsterdam niet.", ["v-kennen"]),
    FB("Er is ___ melk in de koelkast.", ["geen"], "melk sem artigo → geen.", ["v-geen","v-melk"], choices=["geen","niet"], tr="Não há leite no frigorífico."),
  ], diff=3, mins=6)

L(4, "Nunca, ninguém, nada", "nooit, niemand, niets — e responder «não» com educação.",
  ["Usar nooit, niemand e niets", "Recusar com educação"],
  vocab=[V("v-niemand","niemand","ninguém","pronoun"), V("v-niets","niets","nada","pronoun",note="Também «niks» (informal)."),
         V("v-nog-niet","nog niet","ainda não","expression"), V("v-niet-meer","niet meer","já não","expression")],
  ex=[("Niemand is thuis.","Não está ninguém em casa."),("Ik zie niets.","Não vejo nada."),("Ik rook niet meer.","Já não fumo."),("Nog niet.","Ainda não.")],
  gram=[G("g-negativos","Uma só negação","Em neerlandês usa-se **uma só negação** por frase: *ik zie **niets*** (não vejo nada) — e não «ik zie niet niets». O mesmo com **niemand** e **nooit**: *ik rook **nooit***.",
    [("Niemand weet het.","Ninguém sabe."),("Hij zegt niets.","Ele não diz nada.")],
    "Em português a dupla negação é normal («não vejo nada»); em neerlandês seria um erro.")],
  review=["v-nooit","v-niet","v-zien","v-thuis"],
  exs=[
    MA([("niemand","ninguém"),("niets","nada"),("nog niet","ainda não"),("niet meer","já não")], "Negativas.", ["v-niemand","v-niets","v-nog-niet","v-niet-meer"]),
    MC("Como se diz «Não vejo nada»?", ["*Ik zie niets.","Ik zie niet niets.|Uma só negação.","Ik niet zie niets.|Ordem e dupla negação erradas."], "Uma negação: niets.", ["v-niets"]),
    TR("pt-nl","Não está ninguém em casa.", ["Niemand is thuis","Er is niemand thuis"], "niemand como sujeito.", ["v-niemand","v-thuis"]),
    TR("nl-pt","Ik rook niet meer.", ["Já não fumo","Deixei de fumar"], "niet meer = já não.", ["v-niet-meer","v-roken"]),
    TR("nl-pt","Hij zegt niets.", ["(Ele )não diz nada"], "Uma só negação em neerlandês.", ["v-niets","v-zeggen"]),
    FE(["Ik","weet","niet","niets."], 2, "(retirar)", "Uma só negação: ik weet niets.", ["v-niets"]),
    DL([("Eva","Ben je klaar?","Já acabaste?"),("Tom","")], ["*Nee, nog niet.","Nee, niet meer.|«niet meer» = já não.","Nee, niemand.|«niemand» = ninguém."], "nog niet = ainda não.", ["v-nog-niet"]),
    FB("Ik drink ___ alcohol. Nooit.", ["nooit","geen"], "nooit = nunca.", ["v-nooit"], choices=["nooit","niemand","niets"], tr="Nunca bebo álcool. Nunca."),
    LI("Niemand weet het.", ["Niemand weet het"], "Ninguém sabe.", "niemand + verbo.", ["v-niemand","v-weten"]),
    MC("Oferecem-lhe mais café e não quer. O que diz?", ["*Nee, dank je, ik heb genoeg.","Nee, niets!|Soa brusco.","Niemand, dank je.|«niemand» = ninguém."], "Recusar com «nee, dank je» é educado.", ["v-niets"]),
  ], diff=3, mins=6)

L(5, "Dizer que não", "Revisão: niet, geen, nooit, niets, niemand.",
  ["Usar a negação certa em situações reais"],
  ex=[("Ik heb geen tijd en ik ben niet thuis.","Não tenho tempo e não estou em casa.")],
  review=["v-niet","v-geen","v-nooit","v-niets","v-niemand","v-nog-niet","v-kennen","v-weten"],
  exs=[
    MC("Ik spreek ___ Duits.", ["*geen","niet|Línguas sem artigo: geen Duits (também se ouve «niet», mas «geen» é o padrão)."], "Ik spreek geen Duits.", ["v-geen"]),
    MC("Dit is ___ de goede trein.", ["*niet","geen|Com «de» usa-se niet."], "de goede trein → niet.", ["v-niet"]),
    TR("pt-nl","Não tenho filhos.", ["Ik heb geen kinderen"], "kinderen sem artigo → geen.", ["v-geen","v-kind"]),
    TR("pt-nl","Ele não vive aqui.", ["Hij woont hier niet"], "niet no fim.", ["v-niet","v-hier"]),
    TR("nl-pt","Ik ken niemand in Utrecht.", ["Não conheço ninguém em Utrecht"], "Uma só negação.", ["v-niemand","v-kennen"]),
    FE(["Ik","heb","niet","een","auto."], 2, "geen", "een auto → geen auto (sem «een»).", ["v-geen"]),
    WO("Ainda não sei.", ["Ik","weet","het","nog","niet"], "nog niet no fim.", ["v-nog-niet","v-weten"]),
    LI("Ik heb geen idee.", ["Ik heb geen idee"], "Não faço ideia.", "Expressão muito comum.", ["v-geen"]),
    CO("text","Um dia mau", "Vandaag gaat alles mis. Mijn fiets is kapot, er is geen melk en de supermarkt is nog niet open. Ik bel mijn vriendin, maar niemand neemt op.",
       [("Porque não há leite?", ["*O supermercado ainda não abriu","A bicicleta está avariada","Não gosta de leite"]),("O que acontece ao telefone?", ["*Ninguém atende","A namorada está zangada","Não tem telemóvel"])],
       "«niemand neemt op» = ninguém atende.", ["v-nog-niet","v-niemand","v-kapot"]),
    SW("Escreva três coisas que NÃO faz ou NÃO tem (use niet e geen).", ["Ik rook niet(.) Ik heb geen auto(.) Ik drink geen koffie","Ik heb geen [auto|kinderen|hond](.) Ik [rook|werk] niet"],
       ["Usa «geen» com substantivos sem artigo","Usa «niet» com verbos e adjetivos","Uma só negação por frase"], 6, "Modelo: «Ik rook niet. Ik heb geen auto. Ik drink geen koffie.»", ["v-geen","v-niet"]),
  ], diff=3, mins=7)

W()
